`,s.jsxs(t.li,{children:["For example, to tolerate one dishonest worker (",s.jsxs(t.span,{className:"katex",children:[s.jsx(t.span,{className:"katex-mathml",children:s.jsx(t.math,{xmlns:"http://www.w3.org/1998/Math/MathML",children:s.jsxs(t.semantics,{children:[s.jsxs(t.mrow,{children:[s.jsx(t.mi,{children:"f"}),s.jsx(t.mo,{children:"="}),s.jsx(t.mn,{children:"1"})]}),s.jsx(t.annotation,{encoding:"application/x-tex",children:"f = 1"})]})})}),s.jsxs(t.span,{className:"katex-html","aria-hidden":"true",children:[s.jsxs(t.span,{className:"base",children:[s.jsx(t.span,{className:"strut",style:{height:"0.8889em",verticalAlign:"-0.1944em"}}),s.jsx(t.span,{className:"mord mathnormal",style:{marginRight:"0.1076em"},children:"f"}),s.jsx(t.span,{className:"mspace",style:{marginRight:"0.2778em"}}),s.jsx(t.span,{className:"mrel",children:"="}),s.jsx(t.span,{className:"mspace",style:{marginRight:"0.2778em"}})]}),s.jsxs(t.span,{className:"base",children:[s.jsx(t.span,{className:"strut",style:{height:"0.6444em"}}),s.jsx(t.span,{className:"mord",children:"1"})]})]})]}),"), the restaurant needs at least four workers."]}),`
